//! Reproduce the flag-pair, integer-freeze and atomic-storage frontier fixtures.
//! Usage: zig run tools/generate_ssa_transport_canaries.zig -- --output-root NEW
//! Optional --verify-root DIR checks every generated byte against retained inputs.
const std = @import("std");
const u = @import("validation/common.zig");
const Binding = struct { []const u8, []const u8 };
const Variant = enum { alias, bits, signed, poison, constant };
const Case = struct { name: []const u8, bits: u16, variant: Variant };

fn render(c: *u.Context, template: []const u8, bindings: []const Binding) ![]const u8 {
    var result = template;
    for (bindings) |binding| result = try std.mem.replaceOwned(u8, c.a, result, binding[0], binding[1]);
    return result;
}
fn emit(c: *u.Context, w: *std.Io.Writer, template: []const u8, bindings: []const Binding) !void {
    try w.writeAll(try render(c, template, bindings));
}

fn pairs(c: *u.Context) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(c.a);
    const w = &out.writer;
    try w.writeAll("; Integer/flag SSA transport: original producers, parallel PHIs, stable freezes.\ntarget triple = \"x86_64-unknown-linux-gnu\"\n\ndeclare i64 @flag_pair_clobber(i64)\n");
    for ([_]u16{ 8, 16, 32, 64, 128 }) |bits| {
        const ty = try c.fmt("i{d}", .{bits});
        const pair = try c.fmt("{{ {s}, i1 }}", .{ty});
        try w.print("\ndeclare {{ {0s}, i1 }} @llvm.uadd.with.overflow.{0s}({0s}, {0s})\ndeclare {{ {0s}, i1 }} @llvm.usub.with.overflow.{0s}({0s}, {0s})\n\n", .{ty});
        const inputs = if (bits == 128)
            "  %al = zext i64 %a64 to i128\n  %ah = zext i64 %b64 to i128\n  %ash = shl i128 %ah, 64\n  %a = or i128 %al, %ash\n  %bl = zext i64 %b64 to i128\n  %bh = zext i64 %a64 to i128\n  %bsh = shl i128 %bh, 64\n  %b = or i128 %bl, %bsh\n"
        else if (bits < 64)
            try c.fmt("  %a = trunc i64 %a64 to {0s}\n  %b = trunc i64 %b64 to {0s}\n", .{ty})
        else
            "  %a = add i64 %a64, 0\n  %b = add i64 %b64, 0\n";
        const output = if (bits == 128)
            "  %low = trunc i128 %value to i64\n  %upper = lshr i128 %value, 64\n  %high = trunc i128 %upper to i64\n"
        else if (bits < 64)
            try c.fmt("  %low = zext {s} %value to i64\n  %high = add i64 0, 0\n", .{ty})
        else
            "  %low = add i64 %value, 0\n  %high = add i64 0, 0\n";
        try emit(c, w,
            \\define i64 @flag_pair_overflow@BITS@(i64 %a64, i64 %b64, i64 %salt, ptr %out) {
            \\entry:
            \\@INPUTS@  %bit = and i64 %salt, 1
            \\  %choose = icmp ne i64 %bit, 0
            \\  %shift = lshr i64 %salt, 1
            \\  %count = and i64 %shift, 7
            \\  br i1 %choose, label %add, label %subtract
            \\add:
            \\  %sum = call @PAIR@ @llvm.uadd.with.overflow.@TYPE@(@TYPE@ %a, @TYPE@ %b)
            \\  br label %join
            \\subtract:
            \\  %difference = call @PAIR@ @llvm.usub.with.overflow.@TYPE@(@TYPE@ %a, @TYPE@ %b)
            \\  br label %join
            \\join:
            \\  %initial = phi @PAIR@ [ %sum, %add ], [ %difference, %subtract ]
            \\  br label %loop
            \\loop:
            \\  %x = phi @PAIR@ [ %initial, %join ], [ %y, %body ]
            \\  %y = phi @PAIR@ [ { @TYPE@ 17, i1 true }, %join ], [ %x, %body ]
            \\  %i = phi i64 [ 0, %join ], [ %next, %body ]
            \\  %done = icmp eq i64 %i, %count
            \\  br i1 %done, label %exit, label %body
            \\body:
            \\  %next = add i64 %i, 1
            \\  br label %loop
            \\exit:
            \\  %stable = freeze @PAIR@ %x
            \\  %clobber = call i64 @flag_pair_clobber(i64 %salt)
            \\  %flag = extractvalue @PAIR@ %stable, 1
            \\  %value = extractvalue @PAIR@ %stable, 0
            \\@OUTPUT@  %flag64 = zext i1 %flag to i64
            \\  store i64 %low, ptr %out, align 8
            \\  %p1 = getelementptr i8, ptr %out, i64 8
            \\  store i64 %high, ptr %p1, align 8
            \\  %p2 = getelementptr i8, ptr %out, i64 16
            \\  store i64 %flag64, ptr %p2, align 8
            \\  %p3 = getelementptr i8, ptr %out, i64 24
            \\  store i64 %clobber, ptr %p3, align 8
            \\  %r1 = xor i64 %low, %high
            \\  %r2 = xor i64 %r1, %flag64
            \\  %result = xor i64 %r2, %clobber
            \\  ret i64 %result
            \\}
            \\
        , &.{ .{ "@BITS@", try c.fmt("{d}", .{bits}) }, .{ "@TYPE@", ty }, .{ "@PAIR@", pair }, .{ "@INPUTS@", inputs }, .{ "@OUTPUT@", output } });
    }
    for ([_]u16{ 8, 16, 32, 64 }) |bits| {
        const ty = try c.fmt("i{d}", .{bits});
        const inputs = if (bits < 64) try c.fmt("  %a = trunc i64 %a64 to {0s}\n  %b = trunc i64 %b64 to {0s}\n", .{ty}) else "  %a = add i64 %a64, 0\n  %b = add i64 %b64, 0\n";
        const output = if (bits < 64) try c.fmt("  %low = zext {s} %value to i64\n", .{ty}) else "  %low = add i64 %value, 0\n";
        try emit(c, w,
            \\
            \\define i64 @flag_pair_atomic@BITS@(i64 %a64, i64 %b64, i64 %salt, ptr %out) {
            \\entry:
            \\@INPUTS@  %cell = getelementptr i8, ptr %out, i64 32
            \\  %bit = and i64 %salt, 1
            \\  %choose = icmp ne i64 %bit, 0
            \\  br i1 %choose, label %left, label %right
            \\left:
            \\  %a_pair = cmpxchg volatile ptr %cell, @TYPE@ %a, @TYPE@ %b syncscope("singlethread") seq_cst seq_cst, align @ALIGN@
            \\  br label %join
            \\right:
            \\  %b_pair = cmpxchg ptr %cell, @TYPE@ %b, @TYPE@ %a acquire monotonic, align @ALIGN@
            \\  br label %join
            \\join:
            \\  %pair = phi @PAIR@ [ %a_pair, %left ], [ %b_pair, %right ]
            \\  %stable = freeze @PAIR@ %pair
            \\  %clobber = call i64 @flag_pair_clobber(i64 %salt)
            \\  %flag = extractvalue @PAIR@ %stable, 1
            \\  %value = extractvalue @PAIR@ %stable, 0
            \\@OUTPUT@  %flag64 = zext i1 %flag to i64
            \\  store i64 %low, ptr %out, align 8
            \\  %p1 = getelementptr i8, ptr %out, i64 8
            \\  store i64 0, ptr %p1, align 8
            \\  %p2 = getelementptr i8, ptr %out, i64 16
            \\  store i64 %flag64, ptr %p2, align 8
            \\  %p3 = getelementptr i8, ptr %out, i64 24
            \\  store i64 %clobber, ptr %p3, align 8
            \\  %r1 = xor i64 %low, %flag64
            \\  %result = xor i64 %r1, %clobber
            \\  ret i64 %result
            \\}
            \\
        , &.{ .{ "@BITS@", try c.fmt("{d}", .{bits}) }, .{ "@TYPE@", ty }, .{ "@PAIR@", try c.fmt("{{ {s}, i1 }}", .{ty}) }, .{ "@ALIGN@", try c.fmt("{d}", .{bits / 8}) }, .{ "@INPUTS@", inputs }, .{ "@OUTPUT@", output } });
    }
    try w.writeAll(
        \\
        \\define i64 @flag_pair_select(i64 %a, i64 %b, i64 %salt, ptr %out) {
        \\entry:
        \\  %bit = and i64 %salt, 1
        \\  %choose = icmp ne i64 %bit, 0
        \\  %lt = icmp ult i64 %a, %b
        \\  %gt = icmp ugt i64 %a, %b
        \\  %a0 = insertvalue { i64, i1 } poison, i64 %a, 0
        \\  %a1 = insertvalue { i64, i1 } %a0, i1 %lt, 1
        \\  %b0 = insertvalue { i64, i1 } undef, i64 %b, 0
        \\  %b1 = insertvalue { i64, i1 } %b0, i1 %gt, 1
        \\  %selected = select i1 %choose, { i64, i1 } %a1, { i64, i1 } %b1
        \\  %stable = freeze { i64, i1 } %selected
        \\  %clobber = call i64 @flag_pair_clobber(i64 %salt)
        \\  %flag = extractvalue { i64, i1 } %stable, 1
        \\  %value = extractvalue { i64, i1 } %stable, 0
        \\  %flag64 = zext i1 %flag to i64
        \\  store i64 %value, ptr %out, align 8
        \\  %p1 = getelementptr i8, ptr %out, i64 8
        \\  store i64 0, ptr %p1, align 8
        \\  %p2 = getelementptr i8, ptr %out, i64 16
        \\  store i64 %flag64, ptr %p2, align 8
        \\  %p3 = getelementptr i8, ptr %out, i64 24
        \\  store i64 %clobber, ptr %p3, align 8
        \\  %r1 = xor i64 %value, %flag64
        \\  %result = xor i64 %r1, %clobber
        \\  ret i64 %result
        \\}
        \\
        \\define i64 @flag_pair_freeze(i64 %a, i64 %b, i64 %salt, ptr %out) {
        \\entry:
        \\  %stable = freeze { i64, i1 } { i64 4294967297, i1 true }
        \\  %clobber = call i64 @flag_pair_clobber(i64 %salt)
        \\  %value = extractvalue { i64, i1 } %stable, 0
        \\  %flag = extractvalue { i64, i1 } %stable, 1
        \\  %flag64 = zext i1 %flag to i64
        \\  store i64 %value, ptr %out, align 8
        \\  %p1 = getelementptr i8, ptr %out, i64 8
        \\  store i64 0, ptr %p1, align 8
        \\  %p2 = getelementptr i8, ptr %out, i64 16
        \\  store i64 %flag64, ptr %p2, align 8
        \\  %p3 = getelementptr i8, ptr %out, i64 24
        \\  store i64 %clobber, ptr %p3, align 8
        \\  %r1 = xor i64 %value, %flag64
        \\  %result = xor i64 %r1, %clobber
        \\  ret i64 %result
        \\}
        \\
    );
    return out.written();
}

fn freezeCases(c: *u.Context) ![]Case {
    var cases: std.ArrayList(Case) = .empty;
    for ([_]u16{ 33, 40, 48, 56, 63, 65, 96 }) |bits| {
        const variants: []const Variant = if (bits < 64) &.{.alias} else &.{ .bits, .signed, .poison, .constant };
        for (variants) |variant| try cases.append(c.a, .{ .name = try c.fmt("freeze_values_{d}_{s}", .{ bits, @tagName(variant) }), .bits = bits, .variant = variant });
    }
    return cases.items;
}
fn freezes(c: *u.Context, cases: []const Case) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(c.a);
    const w = &out.writer;
    try w.writeAll("target triple = \"x86_64-unknown-linux-gnu\"\ndeclare i64 @frontier_views_clobber(i64)\n");
    for (cases) |case| {
        const ty = try c.fmt("i{d}", .{case.bits});
        const inputs = if (case.bits < 64) try c.fmt("  %raw = trunc i64 %a to {s}\n", .{ty}) else switch (case.variant) {
            .bits => try c.fmt("  %al = zext i64 %a to i128\n  %bh = zext i64 %b to i128\n  %shift = shl i128 %bh, 64\n  %bits = or i128 %al, %shift\n  %raw = trunc i128 %bits to {s}\n", .{ty}),
            .signed => try c.fmt("  %raw = sext i64 %a to {s}\n", .{ty}),
            else => "",
        };
        const observation = if (case.variant == .poison) try c.fmt("  %same = xor {0s} %stable, %stable\n  %low = trunc {0s} %same to i64\n  %high = add i64 0, 0\n", .{ty}) else if (case.bits < 64) try c.fmt("  %low = zext {s} %stable to i64\n  %high = add i64 0, 0\n", .{ty}) else try c.fmt("  %full = zext {s} %stable to i128\n  %low = trunc i128 %full to i64\n  %upper = lshr i128 %full, 64\n  %high = trunc i128 %upper to i64\n", .{ty});
        try emit(c, w,
            \\
            \\define i64 @@NAME@(i64 %a, i64 %b, i64 %salt, ptr %out) {
            \\entry:
            \\@INPUTS@  %stable = freeze @TYPE@ @SOURCE@
            \\  %clobber = call i64 @frontier_views_clobber(i64 %salt)
            \\@OBSERVATION@  %again = freeze @TYPE@ %stable
            \\  %same2 = xor @TYPE@ %stable, %again
            \\  %check = icmp ne @TYPE@ %same2, 0
            \\  %check64 = zext i1 %check to i64
            \\  store i64 %low, ptr %out, align 8
            \\  %p1 = getelementptr i8, ptr %out, i64 8
            \\  store i64 %high, ptr %p1, align 8
            \\  %p2 = getelementptr i8, ptr %out, i64 16
            \\  store i64 %check64, ptr %p2, align 8
            \\  %p3 = getelementptr i8, ptr %out, i64 24
            \\  store i64 %clobber, ptr %p3, align 8
            \\  %r0 = xor i64 %low, %high
            \\  %r1 = xor i64 %r0, %check64
            \\  %r2 = xor i64 %r1, %a
            \\  %result = xor i64 %r2, %clobber
            \\  ret i64 %result
            \\}
            \\
        , &.{ .{ "@NAME@", case.name }, .{ "@TYPE@", ty }, .{ "@INPUTS@", inputs }, .{ "@OBSERVATION@", observation }, .{ "@SOURCE@", switch (case.variant) {
            .poison => "poison",
            .constant => "-1",
            else => "%raw",
        } } });
    }
    return out.written();
}

fn atomics(c: *u.Context) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(c.a);
    const w = &out.writer;
    try w.writeAll("target triple = \"x86_64-unknown-linux-gnu\"\n@frontier_views_global = global [3 x i64] zeroinitializer, align 16\ndeclare i64 @frontier_views_clobber(i64)\n");
    for ([_]u16{ 8, 16, 32, 64 }) |bits| {
        const ty = try c.fmt("i{d}", .{bits});
        const inputs = if (bits < 64) try c.fmt("  %a0 = trunc i64 %a to {0s}\n  %b0 = trunc i64 %b to {0s}\n", .{ty}) else "  %a0 = add i64 %a, 0\n  %b0 = add i64 %b, 0\n";
        var output: std.Io.Writer.Allocating = .init(c.a);
        for ([_][]const u8{ "old", "new", "g" }) |name| {
            if (bits < 64) try output.writer.print("  %{0s}64 = zext {1s} %{0s} to i64\n", .{ name, ty }) else try output.writer.print("  %{0s}64 = add i64 %{0s}, 0\n", .{name});
        }
        try emit(c, w,
            \\
            \\define i64 @atomic_storage_@BITS@(i64 %a, i64 %b, i64 %salt, ptr %out) {
            \\entry:
            \\  %slot = alloca { @TYPE@, [@PAD@ x i8], i64 }, align 16
            \\  %tail = getelementptr i8, ptr %slot, i64 8
            \\  store i64 %salt, ptr %tail, align 8
            \\@INPUTS@  %g = load atomic volatile @TYPE@, ptr getelementptr (i8, ptr @frontier_views_global, i64 8) syncscope("singlethread") acquire, align @ALIGN@
            \\  store atomic volatile @TYPE@ %a0, ptr %slot syncscope("singlethread") release, align @ALIGN@
            \\  %old = atomicrmw add ptr %slot, @TYPE@ %b0 acq_rel, align @ALIGN@
            \\  %new = load atomic volatile @TYPE@, ptr %slot seq_cst, align @ALIGN@
            \\  store atomic @TYPE@ %new, ptr getelementptr (i8, ptr @frontier_views_global, i64 8) seq_cst, align @ALIGN@
            \\  %clobber = call i64 @frontier_views_clobber(i64 %salt)
            \\  %guard = load i64, ptr %tail, align 8
            \\@OUTPUT@  %check = xor i64 %clobber, %guard
            \\  store i64 %old64, ptr %out, align 8
            \\  %p1 = getelementptr i8, ptr %out, i64 8
            \\  store i64 %new64, ptr %p1, align 8
            \\  %p2 = getelementptr i8, ptr %out, i64 16
            \\  store i64 %g64, ptr %p2, align 8
            \\  %p3 = getelementptr i8, ptr %out, i64 24
            \\  store i64 %check, ptr %p3, align 8
            \\  %r0 = xor i64 %old64, %new64
            \\  %r1 = xor i64 %r0, %g64
            \\  %r2 = xor i64 %r1, %a
            \\  %result = xor i64 %r2, %check
            \\  ret i64 %result
            \\}
            \\
        , &.{ .{ "@BITS@", try c.fmt("{d}", .{bits}) }, .{ "@TYPE@", ty }, .{ "@PAD@", try c.fmt("{d}", .{8 - bits / 8}) }, .{ "@ALIGN@", try c.fmt("{d}", .{bits / 8}) }, .{ "@INPUTS@", inputs }, .{ "@OUTPUT@", output.written() } });
    }
    try w.writeAll(
        \\
        \\define i64 @atomic_storage_pointer(i64 %a, i64 %b, i64 %salt, ptr %out) {
        \\entry:
        \\  %slot = alloca { ptr, i64 }, align 16
        \\  %tail = getelementptr i8, ptr %slot, i64 8
        \\  store i64 %salt, ptr %tail, align 8
        \\  %pa = inttoptr i64 %a to ptr
        \\  %pb = inttoptr i64 %b to ptr
        \\  %wrong = xor i64 %a, 1
        \\  %pw = inttoptr i64 %wrong to ptr
        \\  %g = load atomic ptr, ptr getelementptr (i8, ptr @frontier_views_global, i64 8) acquire, align 8
        \\  store atomic ptr %pa, ptr %slot release, align 8
        \\  %bit = and i64 %salt, 1
        \\  %choose = icmp ne i64 %bit, 0
        \\  br i1 %choose, label %yes, label %no
        \\yes:
        \\  %success = cmpxchg ptr %slot, ptr %pa, ptr %pb seq_cst acquire, align 8
        \\  br label %exit
        \\no:
        \\  %failure = cmpxchg ptr %slot, ptr %pw, ptr %pb acq_rel acquire, align 8
        \\  br label %exit
        \\exit:
        \\  %pair = phi { ptr, i1 } [ %success, %yes ], [ %failure, %no ]
        \\  %old = extractvalue { ptr, i1 } %pair, 0
        \\  %flag = extractvalue { ptr, i1 } %pair, 1
        \\  %new = load atomic ptr, ptr %slot seq_cst, align 8
        \\  store atomic ptr %new, ptr getelementptr (i8, ptr @frontier_views_global, i64 8) seq_cst, align 8
        \\  %clobber = call i64 @frontier_views_clobber(i64 %salt)
        \\  %guard = load i64, ptr %tail, align 8
        \\  %old64 = ptrtoint ptr %old to i64
        \\  %new64 = ptrtoint ptr %new to i64
        \\  %g64 = ptrtoint ptr %g to i64
        \\  %flag64 = zext i1 %flag to i64
        \\  %c0 = xor i64 %clobber, %guard
        \\  %check = xor i64 %c0, %flag64
        \\  store i64 %old64, ptr %out, align 8
        \\  %p1 = getelementptr i8, ptr %out, i64 8
        \\  store i64 %new64, ptr %p1, align 8
        \\  %p2 = getelementptr i8, ptr %out, i64 16
        \\  store i64 %g64, ptr %p2, align 8
        \\  %p3 = getelementptr i8, ptr %out, i64 24
        \\  store i64 %check, ptr %p3, align 8
        \\  %r0 = xor i64 %old64, %new64
        \\  %r1 = xor i64 %r0, %g64
        \\  %r2 = xor i64 %r1, %a
        \\  %result = xor i64 %r2, %check
        \\  ret i64 %result
        \\}
        \\
    );
    return out.written();
}

const clobber =
    \\static const uint64_t key = UINT64_C(0xfeedface12345678);
    \\__attribute__((noinline)) uint64_t frontier_views_clobber(uint64_t input) {
    \\    uint64_t result = input ^ key;
    \\    __asm__ volatile(
    \\        "movabs $0x1111111133333333, %%rcx\n\t"
    \\        "movabs $0x2222222244444444, %%rdx\n\t"
    \\        "movabs $0x3333333355555555, %%rdi\n\t"
    \\        "movabs $0x4444444466666666, %%rsi\n\t"
    \\        "movabs $0x5555555577777777, %%r8\n\t"
    \\        "movabs $0x6666666688888888, %%r9\n\t"
    \\        "movabs $0x7777777799999999, %%r10\n\t"
    \\        "movabs $0x88888888aaaaaaaa, %%r11\n\t"
    \\        : "+a"(result) : : "rdi", "rsi", "rdx", "rcx", "r8", "r9", "r10", "r11", "memory", "cc");
    \\    return result;
    \\}
    \\
    \\
;
fn driver(c: *u.Context, names: []const []const u8, cases: ?[]const Case) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(c.a);
    const w = &out.writer;
    try w.writeAll("#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\ntypedef unsigned __int128 u128;\ntypedef uint64_t (*function_t)(uint64_t,uint64_t,uint64_t,uint64_t*);\n");
    for (names) |name| try w.print("extern uint64_t {s}(uint64_t,uint64_t,uint64_t,uint64_t*);\n", .{name});
    try w.writeAll(clobber);
    try w.print("static const function_t functions[]={{{s}}};\n", .{try std.mem.join(c.a, ",", names)});
    if (cases) |entries| {
        try w.writeAll("static const unsigned widths[]={");
        for (entries, 0..) |entry, i| try w.print("{s}{d}", .{ if (i == 0) "" else ",", entry.bits });
        try w.writeAll("};\nstatic const unsigned variants[]={");
        for (entries, 0..) |entry, i| try w.print("{s}{d}", .{ if (i == 0) "" else ",", @as(u8, switch (entry.variant) {
            .alias, .bits => 0,
            .signed => 1,
            .poison => 2,
            .constant => 3,
        }) });
        try w.writeAll("};\n");
    } else try w.writeAll("extern uint64_t frontier_views_global[3];\nstatic const unsigned widths[]={8,16,32,64,64};\n");
    const freeze = cases != null;
    const expected = if (freeze)
        \\ const unsigned bits=widths[which],variant=variants[which];
        \\ const u128 mask=((u128)1<<bits)-1;
        \\ u128 value;
        \\ if(bits<64)value=(u128)a&mask;
        \\ else if(variant==0)value=((u128)a|((u128)b<<64))&mask;
        \\ else if(variant==1)value=(u128)a|((a>>63 ? mask>>64 : 0)<<64);
        \\ else if(variant==2)value=0;
        \\ else value=mask;
        \\ const uint64_t low=(uint64_t)value,high=(uint64_t)(value>>64),third=0,check=salt^key;
    else
        \\ const unsigned bits=widths[which]; const uint64_t mask=bits==64?UINT64_MAX:(UINT64_C(1)<<bits)-1;
        \\ const uint64_t before=a^key;
        \\ frontier_views_global[0]=key;frontier_views_global[1]=before;frontier_views_global[2]=~key;
        \\ const uint64_t low=a&mask,high=which==4 ? (salt&1 ? b:a) : (a+b)&mask,third=before&mask,check=which==4 ? key^(salt&1) : key;
        \\ const uint64_t expected_memory=(before&~mask)|high;
        \\ const uint64_t expected_return=low^high^third^a^check;
    ;
    try emit(c, w,
        \\
        \\static unsigned observations, inject_fault;
        \\static int check(unsigned which,uint64_t a,uint64_t b,uint64_t salt) {
        \\ uint64_t box[8]={key,0,0,0,0,key^1,key^2,key^3}; uint64_t *out=box+1;
        \\@EXPECTED@
        \\ uint64_t actual=functions[which](a,b,salt,out);
        \\ if(inject_fault==1) actual^=1;
        \\ if(inject_fault==2) out[1]^=1;
        \\@FAULT_EXTRA@
        \\ if(actual!=@RETURN@ || out[0]!=low || out[1]!=high || out[2]!=third || out[3]!=check || box[0]!=key || box[5]!=(key^1) || box[6]!=(key^2) || box[7]!=(key^3) || @EXTRA_CHECK@) {
        \\  fprintf(stderr,"frontier mismatch function=%u a=%llx b=%llx salt=%llx fault=%u\n",which,(unsigned long long)a,(unsigned long long)b,(unsigned long long)salt,inject_fault);return 1;
        \\ }
        \\ ++observations;return 0;
        \\}
        \\int main(int argc,char **argv) {
        \\ if(argc==2) inject_fault=(unsigned)strtoul(argv[1],0,10);
        \\ if(argc>2 || inject_fault>5)return 2;
        \\ const uint64_t v[]={0,1,2,0x7fffffff,0x80000000,0x8000000000000000ULL,UINT64_MAX-1,UINT64_MAX};
        \\ const uint64_t s[]={0,1,2,3,14,15,0x123456789abcdef0ULL,UINT64_MAX};
        \\ for(unsigned f=0;f<@COUNT@;f++)for(unsigned i=0;i<8;i++)for(unsigned j=0;j<8;j++)for(unsigned k=0;k<8;k++)if(check(f,v[i],v[j],s[k]))return 1;
        \\ printf("@POPULATION@ observations=%u @CONTRACT@\n",observations);return observations!=@TOTAL@;
        \\}
        \\
    , &.{
        .{ "@EXPECTED@", expected },
        .{ "@FAULT_EXTRA@", if (freeze) " if(inject_fault==3)out[2]^=1;\n if(inject_fault==4)box[0]^=1;\n if(inject_fault==5)out[0]^=1;" else " if(inject_fault==3)frontier_views_global[1]^=1;\n if(inject_fault==4)box[0]^=1;\n if(inject_fault==5)frontier_views_global[2]^=1;" },
        .{ "@RETURN@", if (freeze) "(low^high^a^check)" else "expected_return" },
        .{ "@EXTRA_CHECK@", if (freeze) "0" else "frontier_views_global[0]!=key || frontier_views_global[1]!=expected_memory || frontier_views_global[2]!=~key" },
        .{ "@COUNT@", try c.fmt("{d}", .{names.len}) },
        .{ "@POPULATION@", if (freeze) "integer-freeze-values" else "atomic-storage-views" },
        .{ "@CONTRACT@", if (freeze) "alias=wide=stable=clobbers=guards=preserved" else "ordering=volatile=width=pointer=clobbers=guards=preserved" },
        .{ "@TOTAL@", try c.fmt("{d}", .{names.len * 512}) },
    });
    return out.written();
}

pub fn main(init: std.process.Init) !void {
    var c = try u.Context.init(init);
    const argv = try init.minimal.args.toSlice(c.a);
    const args = try u.Args.parse(c.a, argv[1..], &.{ "output-root", "verify-root" }, &.{});
    const output = try c.newOutput(try args.require("output-root"));
    const cases = try freezeCases(&c);
    const freeze_names = try c.a.alloc([]const u8, cases.len);
    for (cases, freeze_names) |case, *name| name.* = case.name;
    const atomic_names = &.{ "atomic_storage_8", "atomic_storage_16", "atomic_storage_32", "atomic_storage_64", "atomic_storage_pointer" };
    var names = u.object(c.a);
    try u.put(c.a, &names, "integer_freeze_values", try u.strings(c.a, freeze_names));
    try u.put(c.a, &names, "atomic_storage_views", try u.strings(c.a, atomic_names));
    const functions = try std.json.Stringify.valueAlloc(c.a, names, .{ .whitespace = .indent_2 });
    const files = [_]Binding{
        .{ "flag_pair_values.ll", try pairs(&c) },
        .{ "integer_freeze_values.ll", try freezes(&c, cases) },
        .{ "atomic_storage_views.ll", try atomics(&c) },
        .{ "integer_freeze_values_driver.c", try driver(&c, freeze_names, cases) },
        .{ "atomic_storage_views_driver.c", try driver(&c, atomic_names, null) },
        .{ "functions.json", try c.fmt("{s}\n", .{functions}) },
    };
    var hashes = u.object(c.a);
    var passed = true;
    for (files) |file| {
        try c.write(try c.join(&.{ output, file[0] }), file[1]);
        const hash = try u.digestBytes(c.a, file[1]);
        try u.put(c.a, &hashes, file[0], u.s(hash));
        if (args.get("verify-root")) |root| {
            const retained = try c.join(&.{ root, file[0] });
            if (!std.mem.eql(u8, hash, try c.digest(retained))) {
                passed = false;
                try c.print("generated bytes differ: {s}\n", .{file[0]});
            }
        }
    }
    var report = u.object(c.a);
    try u.put(c.a, &report, "schema", u.s("ssa-transport-generation-v1"));
    try u.put(c.a, &report, "status", u.s(if (passed) "passed" else "failed"));
    try u.put(c.a, &report, "files", hashes);
    if (args.get("verify-root")) |root| try u.put(c.a, &report, "verified_against", u.s(try c.join(&.{root})));
    try c.writeJson(try c.join(&.{ output, "generation.json" }), report);
    try c.print("generated {d} files; {s}: {s}/generation.json\n", .{ files.len, if (passed) "passed" else "failed", output });
    if (!passed) std.process.exit(1);
}
